interface PricingStrategy {
  getBasePrice(): number;
  getTaxRate(): number;
  getProcessingFee(): number;
}

const PRICING_STRATEGIES: Record<Tier, PricingStrategy> = {
  premium: {
    getBasePrice: () => 9.99,
    getTaxRate: () => 0.08,
    getProcessingFee: () => 0.029
  },
  enterprise: {
    getBasePrice: () => 49.99,
    getTaxRate: () => 0.08,
    getProcessingFee: () => 0.029
  }
};

function calculateSubscriptionPrice(tier: Tier): number {
  const strategy = PRICING_STRATEGIES[tier];
  const basePrice = strategy.getBasePrice();
  const tax = basePrice * strategy.getTaxRate();
  const fee = basePrice * strategy.getProcessingFee();
  return basePrice + tax + fee;
}

